    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We seek alpha > beta with a nontrivial smallest missing k (>= 30),
# keeping alpha,beta moderate for fast verification.
def find_answer(alpha, beta):
    k = 1
    # Search for the least k where the intersection interval has no integer.
    # For given k, n must satisfy both:
    #   alpha/(k+1) < n <= alpha/k and beta/(k+1) < n <= beta/k.
    # Equivalently, integer n exists iff L <= U, where
    #   L = max(floor(alpha/(k+1)) + 1, floor(beta/(k+1)) + 1),
    #   U = min(floor(alpha/k), floor(beta/k)).
    while True:
        L = max(alpha // (k + 1) + 1, beta // (k + 1) + 1)
        U = min(alpha // k, beta // k)
        if L > U:
            return k
        k += 1
        # Safety cap: should never hit in practice for our ranges.
        if k > 10**7:
            return None
# Try multiple random draws to satisfy difficulty constraints.
for _ in range(200):
    beta = rng.randint(2000, 200000)
    add = rng.randint(max(1, beta // 10), beta)  # alpha in (beta + 0.1*beta .. beta + beta)
    alpha = beta + add
    ans = find_answer(alpha, beta)
    if ans is None:
        continue
    # Enforce nontrivial difficulty and manageable size
    if 30 <= ans <= 1000:
        return {'alpha': alpha, 'beta': beta}
